sys_script_email.script:
(function runMailScript(current, template, email, email_action, event) {

    // current is sysapproval_approver
    // source_id points to the pm_project record being approved
    var project = current.source_id;

    if (project && !project.nil()) {

        var instanceUrl = gs.getProperty('glide.servlet.uri');

        var projectUrl = instanceUrl +
            "now/workspace/project/home/sub/record/pm_project/" +
            project.sys_id +
            "/params/page-name/details/project-table/pm_project" +
            "/project-id/" + project.sys_id +
            "/record-status/1";

        template.print(projectUrl);

    } else {

        template.print('#');

    }

})(current, template, email, email_action, event);
